"""stages.implement.sw: generated by the graph.py split (P1)."""

from __future__ import annotations

from typing import Any

from ... import isa, prompts, state as state_mod
from ...flow import outcome
from ...prompts import SYSTEM_PROMPT
from ...runtime.llm import DEFAULT_MAX_TOOL_ROUNDS
from ...runtime import effects, commands, llm_step, observations, parsing, stage_services, tools
from ...runtime.software_tools import SoftwareCodingToolset
from ...stages import fallbacks, feedback as feedback_mod
from ...stages.implement import delivery, intrinsics
from ...state import CfuDesignState


def _software_evidence_paths(state: CfuDesignState, intrinsics_path: str) -> list[tuple[str, str]]:
    """Artifacts the software rung should read on demand, by path."""
    run_root = str(state.get("run_root", "") or "").rstrip("/")
    paths: list[tuple[str, str]] = []
    if run_root:
        paths.extend(stage_services.existing_evidence(state, [
            (f"{run_root}/07_analysis/workload_analysis.yaml", "workload analysis"),
            (f"{run_root}/08_isa/cfu_isa.yaml",
             "frozen ISA contract" if state.get("isa_contract", True)
             else "contract stage marker (disabled by ablation)"),
            (f"{run_root}/09_implementation/sw_plan.md", "previous software plan (if any)"),
            (f"{run_root}/09_implementation/sw_changed_files.yaml", "previous software change record"),
        ]))
    if intrinsics_path:
        paths.append((intrinsics_path,
                      "generated CFU intrinsics header" if state.get("isa_contract", True)
                      else "agent-authored CFU intrinsics header (editable software target)"))
    return paths


def implement_sw(state: CfuDesignState) -> CfuDesignState:
    """Software rung: the accelerated kernel that calls the new intrinsics."""
    toolbox = stage_services._toolbox_for_stage(state, "implementation")
    isa_spec = state.get("isa_spec", {}) or {}
    targets = stage_services._software_targets(state, toolbox)
    if not targets:
        # No software surface exists (for example a C-project workload without a
        # resolvable kernel): fail the rung instead of spending an LLM call.
        note = "no software target exists for this workload; the software rung cannot run"
        apply_result = {"patch": "", "files": [], "applied": False, "proposed": False, "errors": [note]}
        stage_services._write_software_artifact(state, "", apply_result, [note])
        return {
            "software_plan": "",
            "software_patch": "",
            "implementation_sw_summary": note,
            "llm_raw_outputs": [],
            "changed_sw_files": [],
            "stage_jobs": "validation",
            "errors": [note],
            "gates": outcome.gates(state, {"implementation_sw": {
                "ok": False, "patch": False, "applied": False, "files": [],
                "intrinsics_header": "", "errors": [note],
            }}),
            "iteration_history": state_mod.append_history(state, note),
        }
    errors: list[str] = []
    intrinsics_path = intrinsics._write_intrinsics_header(state, toolbox)
    feedback = "\n\n".join(
        part
        for part in (
            feedback_mod.software_stuck_directive(state),
            feedback_mod.labeled_feedback("sw_build (compile) errors", feedback_mod.check_feedback(state, "sw_build")),
            feedback_mod.sim_feedback(state),
            feedback_mod.labeled_feedback(
                "implementation_sw rejection", feedback_mod.implementation_feedback(state, "implementation_sw")
            ),
        )
        if part
    )
    if feedback:
        # The ledger is repair-context only: appending it to a clean prompt
        # would turn every re-run (e.g. an optimization round) into a "repair".
        ledger = feedback_mod.attempt_ledger_block(state.get("sw_attempts"))
        if ledger:
            feedback = f"{feedback}\n\n{ledger}"
    client = llm_step._llm(state)
    tools_enabled = llm_step._tools_enabled(state, client)
    failures = observations.failure_index(state)
    all_failures = failures.get("failures") or {}
    failure_ids = sorted(
        ident for ident, item in all_failures.items()
        if not isinstance(item, dict) or item.get("status", "current") == "current"
    )
    resolved_failure_ids = sorted(set(all_failures) - set(failure_ids))
    coding_enabled = bool(
        tools_enabled
        and not state.get("dry_run", False)
        and state.get("apply_patch", False)
        and state.get("run_commands", False)
    )
    toolset_kwargs: dict[str, Any] | None = None
    coding_session: dict[str, SoftwareCodingToolset] = {}
    coding_factory = None
    if coding_enabled:
        check_toolbox = stage_services._toolbox_for_stage(state, "validation")
        check_commands = commands._isolated_software_check_commands(state, check_toolbox)
        if check_commands:
            def check_compile() -> dict[str, Any]:
                results = [
                    effects.run_command(
                        state, check_toolbox, command,
                stage="validation", rung="sw_check",
                        command_id="embench_build", timeout=1800, mutate=True)
                    for command in check_commands
                ]
                return next(
                    (item for item in results if item.get("returncode") != 0),
                    results[-1],
                )

            toolset_kwargs = {
                "allowed_targets": frozenset(path for path, _ in targets),
                "check_compile": check_compile,
                "diagnosis_required": bool(feedback),
            }

            def coding_factory(toolbox, **kwargs):
                toolset = SoftwareCodingToolset(toolbox, **kwargs)
                coding_session["toolset"] = toolset
                return toolset
    result, raw_output, tool_calls = llm_step._run_agent_step(
        state,
        toolbox,
        stage="implement",
        label="software",
        artifact_stage="implementation",
        tool_calls_relpath="09_implementation/sw_tool_calls.yaml",
        system=SYSTEM_PROMPT,
        user=prompts.software_prompt(
            state["task"],
            state.get("workload_spec", {}),
            state.get("workload_analysis", ""),
            state.get("design_contract", ""),
            state.get("context", {}),
            profile=state.get("embench_profiles"),
            intrinsics=(isa.render_cfu_intrinsics(isa_spec) if state.get("isa_contract", True)
                        else intrinsics.intrinsics_template_text(str(state.get("workdir", ".")))),
            intrinsics_path=intrinsics_path,
            targets=targets,
            contract_free=not state.get("isa_contract", True),
            feedback=feedback,
            optimization=feedback_mod.optimization_directive(state),
            agent_tools=tools_enabled,
            tool_rounds=int(state.get("max_tool_rounds", DEFAULT_MAX_TOOL_ROUNDS) or DEFAULT_MAX_TOOL_ROUNDS),
            failure_ids=failure_ids,
            resolved_failure_ids=resolved_failure_ids,
            coding_tools=coding_enabled and bool(toolset_kwargs),
            diagnosis_required=bool(feedback),
            artifact_paths=_software_evidence_paths(state, intrinsics_path),
        ),
        fallback=fallbacks.deterministic_software_plan(
            state["task"], state.get("design_contract", "")
        ),
        client=client,
        require_delivery=True,
        deliverable_hint=(
            "the EDIT_BEGIN/SEARCH/REPLACE, FILE_BEGIN/FILE_END, or "
            "PATCH_BEGIN/PATCH_END block required by the delivery protocol"
        ),
        failure_observations=failures,
        toolset_factory=coding_factory,
        toolset_kwargs=toolset_kwargs,
    )
    coding_toolset = coding_session.get("toolset")
    if coding_toolset and coding_toolset.touched_paths:
        apply_result = {
            "patch": tools.extract_patch(result.text),
            "summary": result.text + "\n\nSoftware coding tools applied the audited edits; final delivery was not replayed.",
            "errors": [],
            "applied": True,
            "files": list(coding_toolset.touched_paths),
            "apply_result": {"returncode": 0, "parsed": {"touched_paths": list(coding_toolset.touched_paths)}},
            "gate_ok": True,
            "proposed": True,
        }
        if not any(token in result.text for token in ("EDIT_BEGIN", "FILE_BEGIN", "PATCH_BEGIN")):
            apply_result["errors"].append("tool edits require a final auditable EDIT/FILE/PATCH delivery")
            apply_result["gate_ok"] = False
        if feedback and not coding_toolset.session.diagnosis:
            apply_result["errors"].append("structured repair diagnosis was not accepted before editing")
            apply_result["gate_ok"] = False
    else:
        apply_result = delivery._apply_agent_output(
            state,
            result.text,
            toolbox=toolbox,
            attempts=state.get("sw_attempts"), domain="software",
            require_diagnosis=(
                bool(feedback)
                and bool(getattr(result, "used_llm", False))
                and not bool(coding_toolset and coding_toolset.session.diagnosis)
            ),
        )
    errors.extend(apply_result["errors"])
    intent_error = feedback_mod.tool_intent_error(result.text, str(getattr(result, "degraded_reason", "") or ""))
    if intent_error and not apply_result["applied"]:
        errors.append(intent_error)
    if apply_result["applied"]:
        uses_cfu, cfu_problem = intrinsics._software_exercises_cfu(state, toolbox, targets)
        if not uses_cfu:
            errors.append(cfu_problem)
        if (state.get("optimization_plan") or {}).get("target") == "extend_isa":
            added = set(state.get("isa_added_symbols") or [])
            called = {call["name"] for call in intrinsics._cfu_call_sites(state, toolbox, targets, include_control=True, max_sites=None)}
            if not added.intersection(called):
                errors.append("ISA extension software must call a newly added instruction: " + ", ".join(sorted(added)))
    accepted = bool(apply_result["gate_ok"] and not errors)
    if coding_toolset:
        if accepted:
            coding_toolset.session.commit()
        else:
            coding_toolset.session.rollback()
            apply_result["applied"] = False
            apply_result["files"] = []
            apply_result["gate_ok"] = False
    summary = apply_result["summary"]
    if intrinsics_path:
        summary += f"\n\nWrote {intrinsics_path} from the CFU ISA spec."
    stage_services._write_software_artifact(state, result.text, apply_result, errors, feedback)
    candidate_hash = intrinsics._software_candidate_hash(toolbox, targets) if accepted else ""
    attempt = {
        "response_hash": parsing._attempt_digest(result.text),
        "error_hash": parsing._attempt_digest("\n".join(errors)),
        "search_key": feedback_mod.delivery_search_key(result.text),
        "applied": bool(apply_result["applied"]),
        # Human-readable excerpt for the prior-attempt ledger in repair prompts.
        "error_text": "; ".join(errors)[:300],
    }
    return {
        "software_plan": result.text,
        "software_patch": apply_result["patch"],
        "implementation_sw_summary": summary,
        "changed_sw_files": apply_result["files"],
        "llm_raw_outputs": [raw_output],
        "tool_calls": [llm_step._tool_call_summary(call) for call in tool_calls],
        "sw_attempts": [attempt],
        "stage_jobs": "validation",
        "errors": errors,
        "gates": outcome.gates(state, {"implementation_sw": {
            "ok": apply_result["gate_ok"] and not errors,
            "patch": bool(apply_result["patch"]),
            "applied": apply_result["applied"],
            "files": apply_result["files"],
            "intrinsics_header": intrinsics_path,
            "repair": bool(feedback),
            # Digest of the contract this kernel was written against, so a
            # later iteration can tell whether the ABI moved under it.
            "isa_hash": intrinsics._isa_digest(state),
            "candidate_hash": candidate_hash,
            "tool_calls": len(tool_calls),
            "tools_degraded": str(getattr(result, "degraded_reason", "") or ""),
            "repair_diagnosis": (
                coding_toolset.session.diagnosis if coding_toolset and feedback
                else (("REPAIR_DIAGNOSIS" in result.text) if feedback else None)
            ),
            "response_hash": attempt["response_hash"],
            "error_hash": attempt["error_hash"],
            "errors": errors,
        }}),
        "iteration_history": state_mod.append_history(
            state, "Completed the software rung (accelerated kernel with CFU intrinsics)."
        ),
    }
